      "derivations": [
        {
          "id": "derive-1.1",
          "claim": "For each sign vector $\\tau\\in\\{-1,+1\\}^J$, let $v^\\tau_j=\\tau_jv_j$ on $J$ and zero elsewhere. Absolute values and squares are unchanged, so every $v^\\tau$ belongs to $\\Theta_q(r)$.",
          "step": "1.1",
