        {
          "fact": "F3",
          "source": "thm-parametric-transversality",
          "source_section": "Statement",
          "quote": "Assume the Axiom of Countable Choice $\\mathrm{AC}_\\omega$ ([[def-countable-choice]]). Let $\\mathcal F:M\\times S\\to N$ be a smooth family of maps and let $Z\\subseteq N$\nbe an embedded submanifold. If $\\mathcal F\\pitchfork Z$, then the set of\nparameters $s\\in S$ for which the slice $\\mathcal F_s:M\\to N$ fails to be\ntransverse to $Z$ is a null subset of $S$.",
          "uses": [
