        },
        {
          "fact": "F1",
          "source": "thm-total-variation-is-a-measure",
          "source_section": "Statement",
          "quote": "Let $\\nu$ be a signed measure or a complex measure on $(X,\\mathcal A)$. Then\n$|\\nu|$ is a measure on $(X,\\mathcal A)$.",
          "uses": [
