            "1.2"
          ]
        },
        {
          "fact": "F3",
          "source": "thm-noetherian-ring-quotients-and-localisations",
          "source_section": "Statement",
          "quote": "Let $R$ be a Noetherian commutative ring. Then\n\n1. $R/I$ is Noetherian for every ideal $I$ of $R$\n   ([[def-quotient-ring]]), and\n2. $S^{-1}R$ is Noetherian for every multiplicative subset $S\\subseteq R$\n   ([[def-multiplicative-subset-and-localisation]]).\n\nBoth cases include their degenerate instances: $I=R$ makes $R/I$ the zero ring,\nand $0\\in S$ makes $S^{-1}R$ the zero ring, and the zero ring is Noetherian.",
          "uses": [
            "1.2"
          ]
