      "derivations": [
        {
          "id": "step-1-1",
          "claim": "Let $m$ be the unique maximum. The two components of $a\\setminus\\{m\\}$ are strictly monotone in height, so each intermediate regular level meets $a$ in exactly two points. In a Morse chart on $a$ near $m$, the height is $h(m)-t^2$; a short level arc joining the two nearby points and the subarc through $m$ bound a small embedded cap disk. Under [F1], the two points on all lower regular levels form a smooth path of distinct ordered pairs in $S^2$.",
          "step": "1.1",
          "inputs": [
