        {
          "fact": "F4",
          "source": "lem-seifert-stabilization-preserves-levine-tristram-signature",
          "source_section": "Statement",
          "quote": "Assume full AC. For every $\\omega\\in S^1\\setminus\\{1\\}$, changing an ordered basis by an integral unimodular congruence or changing a knot Seifert matrix by either elementary enlargement or reduction preserves the signature of $H_\\omega$. Consequently, the nonroot Levine–Tristram signature and its one-sided-average value at every Alexander root are independent of the spanning surface and basis.",
          "uses": [
            "1.1",
            "2.1",
            "3.1"
          ]
