          ]
        },
        {
          "fact": "F1",
          "source": "thm-higher-dimensional-spheres-are-simply-connected",
          "source_section": "Statement",
          "quote": "For every natural number $n\\ge2$, the unit sphere $S^n\\subseteq\\mathbb R^{n+1}$ is simply connected ([[def-simply-connected]]).",
          "uses": [
            "1.1"
          ]
        },
        {
          "fact": "F2",
          "source": "def-universal-covering-space",
          "source_section": "Definition",
          "quote": "A **universal covering space** of $B$ is a covering map $p:\\widetilde B\\to B$ whose total space $\\widetilde B$ is simply connected ([[def-covering-map-and-evenly-covered-neighbourhoods]], [[def-simply-connected]]).",
          "uses": [
            "1.1"
