      "derivations": [
        {
          "id": "step-1-1",
          "claim": "Since $\\gcd(p,q)=1$, Bézout's identity gives integers $r,s$ with $ps-qr=1$. The integer matrix with columns $(p,q)$ and $(r,s)$ is unimodular, so its linear map on $\\mathbb R^2$ descends to a torus homeomorphism. The image of a coordinate circle is embedded and has class $p[\\mu]+q[\\lambda]$; reversing its parameter changes both coefficients' signs and leaves the unoriented curve unchanged. Thus every primitive pair defines a slope.",
          "step": "1.1",
          "inputs": [
