      "derivations": [
        {
          "id": "step-1-1",
          "claim": "By [A1] and [F1], choose a finite triangulation $\\mathcal T$ of $M$. Its $1$-skeleton is connected: if it were disconnected, each simplex would have all its vertices in a single graph component because every pair of vertices of a simplex is joined by an edge; the realization would therefore be a disjoint union of nonempty subcomplexes, contrary to connectedness of $M$.",
          "step": "1.1",
          "inputs": [
            "given",
            "A1",
